import { content } from "@/lib/content";

/**
 * The wobbly divider. Path is generated by Rough.js at build time and lives in
 * content.generated.json, so this stays a server component with no client JS.
 * Stretched horizontally — the wobble is vertical, so it survives the scale.
 */
export function SketchRule({ className = "" }: { className?: string }) {
  return (
    <div className={`hr-sketch ${className}`} aria-hidden="true">
      <svg viewBox="0 0 900 12" preserveAspectRatio="none">
        <path
          d={content.rulePath}
          fill="none"
          stroke="currentColor"
          strokeWidth={1.6}
          strokeLinecap="round"
        />
      </svg>
    </div>
  );
}
